func (v ItemsValue) ToObjectValue(ctx context.Context) (basetypes.ObjectValue, diag.Diagnostics) {
	var diags diag.Diagnostics

	var tagsVal basetypes.MapValue
	switch {
	case v.Tags.IsUnknown():
		tagsVal = types.MapUnknown(types.StringType)
	case v.Tags.IsNull():
		tagsVal = types.MapNull(types.StringType)
	default:
		var d diag.Diagnostics
		tagsVal, d = types.MapValue(types.StringType, v.Tags.Elements())
		diags.Append(d...)
	}

	if diags.HasError() {
		return types.ObjectUnknown(map[string]attr.Type{
			"account_id": basetypes.StringType{},
			"cost_estimation_potential_freed_commitments":              basetypes.Float64Type{},
			"cost_estimation_potential_increased_commitments_required": basetypes.Float64Type{},
			"cost_estimation_potential_increased_costs":                basetypes.Float64Type{},
			"cost_estimation_potential_savings":                        basetypes.Float64Type{},
			"detection_time":                                           basetypes.StringType{},
			"first_flow_id":                                            basetypes.StringType{},
			"id":                                                       basetypes.Int64Type{},
			"is_active":                                                basetypes.BoolType{},
			"issued_resource_id":                                       basetypes.StringType{},
			"issued_resource_name":                                     basetypes.StringType{},
			"last_flow_id":                                             basetypes.StringType{},
			"provider":                                                 basetypes.StringType{},
			"provider_identifier":                                      basetypes.StringType{},
			"region":                                                   basetypes.StringType{},
			"resolved_time":                                            basetypes.StringType{},
			"resource_class":                                           basetypes.StringType{},
			"rule_id":                                                  basetypes.Int64Type{},
			"snoozed":                                                  basetypes.BoolType{},
			"solved":                                                   basetypes.BoolType{},
			"tags": basetypes.MapType{
				ElemType: types.StringType,
			},
		}), diags
	}

	attributeTypes := map[string]attr.Type{
		"account_id": basetypes.StringType{},
		"cost_estimation_potential_freed_commitments":              basetypes.Float64Type{},
		"cost_estimation_potential_increased_commitments_required": basetypes.Float64Type{},
		"cost_estimation_potential_increased_costs":                basetypes.Float64Type{},
		"cost_estimation_potential_savings":                        basetypes.Float64Type{},
		"detection_time":                                           basetypes.StringType{},
		"first_flow_id":                                            basetypes.StringType{},
		"id":                                                       basetypes.Int64Type{},
		"is_active":                                                basetypes.BoolType{},
		"issued_resource_id":                                       basetypes.StringType{},
		"issued_resource_name":                                     basetypes.StringType{},
		"last_flow_id":                                             basetypes.StringType{},
		"provider":                                                 basetypes.StringType{},
		"provider_identifier":                                      basetypes.StringType{},
		"region":                                                   basetypes.StringType{},
		"resolved_time":                                            basetypes.StringType{},
		"resource_class":                                           basetypes.StringType{},
		"rule_id":                                                  basetypes.Int64Type{},
		"snoozed":                                                  basetypes.BoolType{},
		"solved":                                                   basetypes.BoolType{},
		"tags": basetypes.MapType{
			ElemType: types.StringType,
		},
	}

	if v.IsNull() {
		return types.ObjectNull(attributeTypes), diags
	}

	if v.IsUnknown() {
		return types.ObjectUnknown(attributeTypes), diags
	}

	objVal, diags := types.ObjectValue(
		attributeTypes,
		map[string]attr.Value{
			"account_id": v.AccountId,
			"cost_estimation_potential_freed_commitments":              v.CostEstimationPotentialFreedCommitments,
			"cost_estimation_potential_increased_commitments_required": v.CostEstimationPotentialIncreasedCommitmentsRequired,
			"cost_estimation_potential_increased_costs":                v.CostEstimationPotentialIncreasedCosts,
			"cost_estimation_potential_savings":                        v.CostEstimationPotentialSavings,
			"detection_time":                                           v.DetectionTime,
			"first_flow_id":                                            v.FirstFlowId,
			"id":                                                       v.Id,
			"is_active":                                                v.IsActive,
			"issued_resource_id":                                       v.IssuedResourceId,
			"issued_resource_name":                                     v.IssuedResourceName,
			"last_flow_id":                                             v.LastFlowId,
			"provider":                                                 v.Provider,
			"provider_identifier":                                      v.ProviderIdentifier,
			"region":                                                   v.Region,
			"resolved_time":                                            v.ResolvedTime,
			"resource_class":                                           v.ResourceClass,
			"rule_id":                                                  v.RuleId,
			"snoozed":                                                  v.Snoozed,
			"solved":                                                   v.Solved,
			"tags":                                                     tagsVal,
		})

	return objVal, diags
}

